//! The library's own strings: a typed `leptos_i18n` catalogue generated by
//! `build.rs` from `locales/<code>.json`, read in the current
//! [`Language`](crate::language::Language).
//!
//! A component takes [`strings`] once, then reads each string inside a
//! reactive closure, so a language switch re-renders that text alone:
//!
//! ```ignore
//! let t = strings();
//! view! { <span>{move || td_string!(t.locale(), settings)}</span> }
//! ```
//!
//! `leptos_i18n`'s own `I18nContext` is not used: it would bring its own
//! cookie, `Accept-Language` detection and `<html lang>` writer, a second
//! owner of what [`crate::language::resolve_language`] decides.

#[allow(missing_docs, unused, clippy::all, clippy::pedantic)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/i18n/mod.rs"));
}

pub(crate) use generated::i18n::Locale;

use leptos::prelude::*;

use crate::language::{Language, language_signal};

/// The library's catalogue, bound to [`language_signal`]: copy it into
/// closures, read [`Strings::locale`] inside them.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Strings(RwSignal<Language>);

impl Strings {
    /// The current language's catalogue locale. Tracked: a closure reading
    /// it runs again when the language changes.
    pub(crate) fn locale(self) -> Locale {
        Locale::from(self.0.get())
    }
}

/// The library's strings, in the language of [`language_signal`].
pub(crate) fn strings() -> Strings {
    Strings(language_signal())
}

impl From<Language> for Locale {
    /// Exhaustive: a new [`Language`] does not build until the library has
    /// its strings (and a `locales/<code>.json`).
    fn from(language: Language) -> Self {
        match language {
            Language::En => Locale::en,
            Language::Fr => Locale::fr,
            Language::Vi => Locale::vi,
        }
    }
}

#[cfg(test)]
mod tests {
    use leptos_i18n::td_string;

    use super::*;

    #[test]
    fn every_language_reads_its_own_strings() {
        let settings: Vec<&str> = Language::ALL
            .into_iter()
            .map(|language| td_string!(Locale::from(language), settings))
            .collect();
        assert_eq!(settings, ["Settings", "Paramètres", "Cài đặt"]);
    }

    #[test]
    fn strings_follow_the_language_signal() {
        Owner::new().with(|| {
            let t = strings();
            let label = Signal::derive(move || td_string!(t.locale(), back));
            assert_eq!(label.get(), "Back");
            language_signal().set(Language::Vi);
            assert_eq!(label.get(), "Quay lại", "switched live");
            language_signal().set(Language::Fr);
            assert_eq!(label.get(), "Retour");
        });
    }

    #[test]
    fn carousel_strings_in_three_languages() {
        let previous: Vec<&str> = Language::ALL
            .into_iter()
            .map(|language| td_string!(Locale::from(language), carousel_previous))
            .collect();
        assert_eq!(previous, ["Previous", "Précédent", "Trước"]);
        let next: Vec<&str> = Language::ALL
            .into_iter()
            .map(|language| td_string!(Locale::from(language), carousel_next))
            .collect();
        assert_eq!(next, ["Next", "Suivant", "Tiếp"]);
        let slide: Vec<String> = Language::ALL
            .into_iter()
            .map(|language| {
                td_string!(Locale::from(language), carousel_slide, n = 2, total = 5).to_string()
            })
            .collect();
        assert_eq!(slide, ["2 of 5", "2 sur 5", "2 trên 5"]);
    }
}
